const rows = $input.all().map(i => i.json);
// Groq free tier allows ~8000 tokens per request (prompt + answer), so keep the sample small.
// Skip very short reviews (generic praise / gibberish) - they add tokens but no insight.
// Keep reviews short enough to send WHOLE (no truncation) so quotes are always complete sentences.
const clean = r => String(r.content || '').replace(/\s+/g, ' ').trim();
const useful = rows.filter(r => { const c = clean(r); return c.split(' ').length >= 4 && c.length <= 160; });
const shuffle = arr => {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
};
const low = shuffle(useful.filter(r => Number(r.score) <= 3)).slice(0, 50);
const high = shuffle(useful.filter(r => Number(r.score) >= 4)).slice(0, 8);
const picked = [...low, ...high];

const text = picked
  .map(r => `[${r.score}★] ${clean(r)}`)
  .join('\n');

return [{ json: {
  reviews_text: text,
  total_reviews: rows.length,
  sent_to_ai: picked.length,
  date: new Date().toISOString().slice(0, 10)
}}];

